package com.handsfree.probes

import android.Manifest.permission.*

data class Experiment(val id: String, val title: String, val steps: String, val required: List<String> = emptyList(), val optional: List<String> = emptyList())
object Experiments {
    private val listening = listOf(RECORD_AUDIO, READ_PHONE_STATE)
    val all = listOf(
        Experiment("T1a", "Default recognition proxy", "Choose probes as assistant in system settings. Grant microphone and phone-state access, then Start and speak. Repeat and cancel. Compare Gboard manually. This client deliberately uses the default recognition engine.", listening),
        Experiment("T1b", "Screening to ringing session", "Request CALL_SCREENING and choose probes as assistant. Start, then call each active SIM from another phone. Test a saved contact with and without contact consent/permission. Connect HFP. Say Answer while ringing. End ringing and inspect client-close timing; check the microphone indicator manually.", listening + ANSWER_PHONE_CALLS, listOf(READ_CONTACTS, BLUETOOTH_CONNECT)),
        Experiment("T1c", "Audio mode and legacy caller number", "Start without phone permissions first; make, answer and end a test call. Audio-mode monitoring needs no dangerous permission. Then grant phone-state/call-log consent and permissions, keep the assistant role, and repeat for the legacy number-present measurement.", optional = listOf(READ_PHONE_STATE, READ_CALL_LOG)),
        Experiment("T2", "Launch intents from a session", "Enter a test number, query, destination and app package. Select the outgoing phone account. Start to show the session, turn the screen off and invoke the assistant. Say call, play, navigation, timer, or app in the session, one test at a time. Buttons also work with the screen on. Calling requires a second spoken confirmation. Record any blocked-launch dialog manually.", listening, listOf(CALL_PHONE, READ_CONTACTS, BLUETOOTH_CONNECT)),
        Experiment("T3", "Background microphone FGS", "Choose probes as assistant and Start. Switch apps within five seconds. For A-5 select Screen-off measurement before Start, wait for capture to begin, speak for two seconds, then turn the screen off and keep speaking through the 15-second window. Normal mode captures for three seconds and stops on screen off. Inspect per-second counts and end reason. Repeat after withdrawing the assistant role with the same permissions.", listOf(RECORD_AUDIO, POST_NOTIFICATIONS)),
        Experiment("T4", "SCO latency and intelligibility", "Pair HFP and grant Bluetooth access. Start for 20 route-open measurements and ten fixed sentences. Inspect attempts, successes, timeouts, failures and success rate alongside successful-open median/p90; PASS requires 20 attempts, success rate at least 90%, median and p90 both below 2000 ms. Enter how many sentences you understood and save the observation. Unplug the headset during speech to verify stopping.", listOf(BLUETOOTH_CONNECT)),
        Experiment("T5", "WhatsApp call actions", "Grant notification-listener access in system settings and its independent consent here. Start to inspect a voice-call notification. On a new incoming WhatsApp voice call press Answer or Decline explicitly. Repeat on Android 14/15/16 with PIN: arm the trial, lock, invoke the assistant and use the session buttons or say Answer/Decline with optional microphone/phone-state consent. Existing notifications are marked visible, never read automatically.", listOf(ProbeNotificationListener.ACCESS), listOf(RECORD_AUDIO, READ_PHONE_STATE)),
        Experiment("T6", "Player search: cold and active", "Select a discovered player package and its version. Close the player manually for a cold trial; repeat while active. Choose explicit intent or platform controller separately. The controller requires notification-access consent and an exposed media session that advertises playFromSearch. Within four seconds from the request, the bound session must be playing and all query tokens must match its title or artist (case-insensitive). Inspect success, no_session, unsupported, timeout_no_playing, or playing_no_match. Record picker appearance manually.", optional = listOf(ProbeNotificationListener.ACCESS)),
        Experiment("T7", "Transient focus from session", "Play music, turn the screen off, invoke the assistant session; focus is requested on show. Request focus also repeats it with the screen on. Do not start an FGS. Record manually whether music ducked; the numeric focus result is recorded automatically."),
        Experiment("T8", "PCM during a cellular call", "Start a real cellular call, keep it active, then Start this three-second microphone diagnostic. It records only sample counts/RMS, never audio. This is not voice-command listening. A zero count or platform rejection is a measured result.", listOf(RECORD_AUDIO, READ_PHONE_STATE, POST_NOTIFICATIONS)),
        Experiment("T9", "Assistant role request dialog", "Start to call isRoleAvailable and createRequestRoleIntent for ROLE_ASSISTANT. Record whether a dialog appeared and its result. The normal assistant selection button opens system settings instead."),
        Experiment("T10", "Session intents above PIN lock", "Set a PIN and enter a saved test number, navigation destination and outgoing account. Grant selected permissions and consent. Start, lock the phone, invoke the assistant and say navigation, timer, or call. Confirm the call by voice. Also say read or send, or use their buttons, with personal results off and on. Both record Allow or Deny(LOCKED). Read speaks the latest visible notification summary only after Allow and optional notification access/consent. Send only evaluates a synthetic preparation and never sends. Record any unlock request and whether directions were audible.", listening, listOf(CALL_PHONE, READ_CONTACTS, BLUETOOTH_CONNECT, ProbeNotificationListener.ACCESS)),
        Experiment("T11", "Headset and steering-wheel buttons", "Connect the headset/car. Start in passive mode first, then compare capture-session mode, which changes routing. Press short and long while ringing and outside ringing. Save the observed result: answered, assistant invoked, or nothing. Phone-state access is optional for state context.", optional = listOf(READ_PHONE_STATE)),
        Experiment("T12", "Permission snapshots around role", "Start before choosing the assistant role. Choose probes in system settings without extra permission dialogs, then Start again. Withdraw the role and repeat. Compare every declared permission with the previous snapshot."),
        Experiment("T13", "Audio-source stop with AEC", "API 33+ only. Pair the car, grant microphone/phone-state/Bluetooth consent and permissions. Start 20 trials. Say stop while each fixed sentence plays. The app opens VOICE_COMMUNICATION with AEC and supplies EXTRA_AUDIO_SOURCE. Record the stop count and whether recognition was on device.", listening + BLUETOOTH_CONNECT),
    )
    fun find(id: String): Experiment? = all.find { it.id == id }
}
data class ProbeConfig(
    val number: String = "", val query: String = "jazz", val destination: String = "London",
    val appPackage: String = "", val phoneAccountIndex: Int = 0,
    val personalResultsOnLock: Boolean = false,
    val screenOffMeasurement: Boolean = false,
    val mediaCold: Boolean = true, val mediaMethod: String = "intent", val captureButtons: Boolean = false,
)
